INSERT INTO directores (id_director, nombre, apellido, descripcion) VALUES
                                                                        (1, 'Christopher', 'Nolan', 'Director y guionista británico-estadounidense. Conocido por Inception e Interstellar.'),
                                                                        (2, 'Quentin', 'Tarantino', 'Director y guionista estadounidense. Conocido por Pulp Fiction y Kill Bill.'),
                                                                        (3, 'Greta', 'Gerwig', 'Directora y guionista estadounidense. Conocida por Lady Bird, Mujercitas y Barbie.'),
                                                                        (4, 'Denis', 'Villeneuve', 'Director canadiense. Conocido por La llegada y Dune.'),
                                                                        (5, 'Martin', 'Scorsese', 'Director estadounidense. Conocido por Taxi Driver, Buenos muchachos y Los infiltrados.'),
                                                                        (6, 'Steven', 'Spielberg', 'Director estadounidense. Conocido por Tiburón, E.T. y Jurassic Park.'),
                                                                        (7, 'Hayao', 'Miyazaki', 'Director japonés, cofundador del Studio Ghibli.'),
                                                                        (8, 'Joon-ho', 'Bong', 'Director surcoreano. Conocido por Memorias de un asesino y Parásitos.'),
                                                                        (9, 'John', 'Lasseter', 'Director estadounidense de animación. Dirigió Toy Story.'),
                                                                        (10, 'Peter', 'Jackson', 'Director neozelandés. Dirigió la trilogía de El Señor de los Anillos.'),
                                                                        (11, 'James', 'Cameron', 'Director canadiense. Conocido por Terminator, Titanic y Avatar.'),
                                                                        (12, 'Ridley', 'Scott', 'Director británico. Conocido por Alien, Blade Runner y Gladiador.'),
                                                                        (13, 'Juan José', 'Campanella', 'Director argentino. Conocido por El hijo de la novia y El secreto de sus ojos.'),
                                                                        (14, 'Damián', 'Szifron', 'Director y guionista argentino. Conocido por Relatos salvajes.'),
                                                                        (15, 'Vince', 'Gilligan', 'Creador de Breaking Bad y Better Call Saul.'),
                                                                        (16, 'David', 'Benioff', 'Guionista estadounidense, cocreador de Game of Thrones.'),
                                                                        (17, 'Baran', 'bo Odar', 'Director alemán, cocreador de la serie Dark.'),
                                                                        (18, 'Peter', 'Morgan', 'Guionista británico, creador de The Crown.'),
                                                                        (19, 'Steven', 'Moffat', 'Guionista británico, cocreador de Sherlock.'),
                                                                        (20, 'Craig', 'Mazin', 'Guionista estadounidense, creador de Chernobyl y cocreador de The Last of Us.'),
                                                                        (21, 'Jesse', 'Armstrong', 'Guionista británico, creador de Succession.'),
                                                                        (22, 'Jon', 'Favreau', 'Director y actor estadounidense, creador de The Mandalorian.'),
                                                                        (23, 'Steven', 'Knight', 'Guionista británico, creador de Peaky Blinders.'),
                                                                        (24, 'Dong-hyuk', 'Hwang', 'Director surcoreano, creador de El juego del calamar.'),
                                                                        (25, 'Noah', 'Hawley', 'Guionista estadounidense, creador de la serie Fargo.'),
                                                                        (26, 'Phoebe', 'Waller-Bridge', 'Guionista y actriz británica, creadora de Fleabag.'),
                                                                        (27, 'Marta', 'Kauffman', 'Guionista estadounidense, cocreadora de Friends.');
INSERT INTO peliculas (id_pelicula, nombre, duracionMinutos, clasificacion, baja, id_director, genero, fechaEstreno, descripcion) VALUES
                                                                                                                                      (1, 'Inception', 148, 'T', FALSE, 1, 'SciFi', '2010-07-16', 'Un especialista en entrar en los sueños recibe el encargo de implantar una idea.'),
                                                                                                                                      (2, 'Interstellar', 169, 'T', FALSE, 1, 'SciFi', '2014-11-07', 'Una misión espacial busca un nuevo hogar para la humanidad mientras la Tierra se deteriora.'),
                                                                                                                                      (3, 'Pulp Fiction', 154, 'M', FALSE, 2, 'Suspenso', '1994-10-14', 'Historias criminales que se cruzan a lo largo de varios días en Los Ángeles.'),
                                                                                                                                      (4, 'Barbie', 114, 'T', FALSE, 3, 'Comedia', '2023-07-21', 'Barbie sale de su mundo perfecto y descubre cómo la ven quienes viven fuera de él.'),
                                                                                                                                      (5, 'Dune', 155, 'T', FALSE, 4, 'SciFi', '2021-10-22', 'Paul Atreides llega a un planeta desértico que concentra un recurso disputado por el Imperio.'),
                                                                                                                                      (6, 'The Departed', 151, 'M', FALSE, 5, 'Suspenso', '2006-10-06', 'Un policía infiltrado y un informante de la mafia intentan descubrirse en Boston.'),
                                                                                                                                      (7, 'Jurassic Park', 127, 'T', FALSE, 6, 'SciFi', '1993-06-11', 'Un parque con dinosaurios clonados pone a prueba a sus primeros visitantes.'),
                                                                                                                                      (8, 'El viaje de Chihiro', 125, 'E10Plus', TRUE, 7, 'Animacion', '2001-07-20', 'Chihiro se adentra en un mundo de espíritus para encontrar la manera de salvar a sus padres.'),
                                                                                                                                      (9, 'Parásitos', 132, 'M', FALSE, 8, 'Drama', '2019-05-30', 'Una familia consigue trabajo en una casa acomodada y queda atrapada en una red de engaños.'),
                                                                                                                                      (10, 'Toy Story', 81, 'E', FALSE, 9, 'Animacion', '1995-11-22', 'El vaquero Woody intenta encontrar su lugar cuando llega un juguete espacial al cuarto de Andy.'),
                                                                                                                                      (11, 'El Señor de los Anillos: La Comunidad del Anillo', 178, 'T', FALSE, 10, 'Fantasia', '2001-12-19', 'Un hobbit emprende un viaje para destruir un anillo que amenaza la Tierra Media.'),
                                                                                                                                      (12, 'Avatar', 162, 'T', FALSE, 11, 'SciFi', '2009-12-18', 'Un exmarine conoce a los habitantes de Pandora mientras participa en una misión humana.'),
                                                                                                                                      (13, 'Gladiador', 155, 'M', TRUE, 12, 'Accion', '2000-05-05', 'Un general romano convertido en gladiador busca justicia en la arena.'),
                                                                                                                                      (14, 'El secreto de sus ojos', 129, 'M', FALSE, 13, 'Suspenso', '2009-08-13', 'Un empleado judicial retirado vuelve sobre un crimen sin resolver y los recuerdos de aquella época.'),
                                                                                                                                      (15, 'Relatos salvajes', 122, 'M', FALSE, 14, 'Comedia', '2014-08-21', 'Seis historias independientes muestran qué sucede cuando sus protagonistas pierden la paciencia.');
INSERT INTO series (id_serie, nombre, duracionMinutos, clasificacion, baja, id_director, genero, cantidadCapitulos, cantidadTemporadas, descripcion) VALUES
                                                                                                                                                         (1, 'Breaking Bad', 47, 'M', FALSE, 15, 'Drama', 62, 5, 'Un profesor de química se asocia con un exalumno y entra en el negocio de las drogas.'),
                                                                                                                                                         (2, 'Better Call Saul', 46, 'M', FALSE, 15, 'Drama', 63, 6, 'Jimmy McGill intenta hacerse un lugar como abogado mientras construye la identidad de Saul Goodman.'),
                                                                                                                                                         (3, 'Game of Thrones', 57, 'M', FALSE, 16, 'Fantasia', 73, 8, 'Familias rivales se disputan el poder en Poniente mientras crece una amenaza en el norte.'),
                                                                                                                                                         (4, 'Dark', 55, 'M', TRUE, 17, 'SciFi', 26, 3, 'La desaparición de un chico revela conexiones entre varias generaciones de un pueblo alemán.'),
                                                                                                                                                         (5, 'The Crown', 58, 'M', FALSE, 18, 'Drama', 60, 6, 'Distintas etapas del reinado de Isabel II se cuentan a través de conflictos familiares y políticos.'),
                                                                                                                                                         (6, 'Sherlock', 88, 'T', FALSE, 19, 'Suspenso', 13, 4, 'Sherlock Holmes y John Watson resuelven crímenes en una versión contemporánea de Londres.'),
                                                                                                                                                         (7, 'Chernobyl', 60, 'M', FALSE, 20, 'Drama', 5, 1, 'La miniserie reconstruye el accidente nuclear y las decisiones tomadas en los días posteriores.'),
                                                                                                                                                         (8, 'The Last of Us', 55, 'M', FALSE, 20, 'Terror', 16, 2, 'Joel y Ellie atraviesan un mundo devastado mientras surgen alianzas y amenazas en el camino.'),
                                                                                                                                                         (9, 'Succession', 60, 'M', FALSE, 21, 'Drama', 39, 4, 'Los miembros de una familia compiten por dirigir el conglomerado de medios de su padre.'),
                                                                                                                                                         (10, 'The Mandalorian', 40, 'T', FALSE, 22, 'SciFi', 24, 3, 'Un cazarrecompensas viaja por la galaxia junto a un pequeño al que debe proteger.'),
                                                                                                                                                         (11, 'Peaky Blinders', 60, 'M', FALSE, 23, 'Drama', 36, 6, 'Una familia de Birmingham intenta ampliar su poder en los años posteriores a la Primera Guerra Mundial.'),
                                                                                                                                                         (12, 'El juego del calamar', 60, 'M', TRUE, 24, 'Suspenso', 22, 3, 'Personas endeudadas compiten por un premio en una serie de juegos con consecuencias letales.'),
                                                                                                                                                         (13, 'Fargo', 60, 'M', FALSE, 25, 'Suspenso', 51, 5, 'Cada temporada sigue un caso criminal distinto marcado por casualidades y humor negro.'),
                                                                                                                                                         (14, 'Fleabag', 27, 'M', FALSE, 26, 'Comedia', 12, 2, 'Una mujer londinense enfrenta pérdidas personales y vínculos familiares con humor ácido.'),
                                                                                                                                                         (15, 'Friends', 22, 'T', FALSE, 27, 'Comedia', 236, 10, 'Seis amigos comparten trabajo, relaciones y la vida diaria en Nueva York.');
INSERT INTO videojuegos (id_videojuego, nombre, duracionMinutos, clasificacion, baja, genero, dificultad, descripcion) VALUES
                                                                                                                           (1, 'Hades', 1320, 'T', FALSE, 'RogueLike', 3, 'Zagreo cambia de armas y recibe ayuda de los dioses para intentar escapar del inframundo.'),
                                                                                                                           (2, 'The Legend of Zelda: Breath of the Wild', 3000, 'E10Plus', FALSE, 'MundoAbierto', 3, 'Link explora Hyrule a su ritmo, descubre santuarios y recupera sus recuerdos.'),
                                                                                                                           (3, 'Celeste', 480, 'E10Plus', FALSE, 'Plataformas', 4, 'Madeline escala una montaña en un juego de plataformas que exige precisión y paciencia.'),
                                                                                                                           (4, 'Super Mario Odyssey', 780, 'E10Plus', FALSE, 'Plataformas', 2, 'Mario recorre distintos reinos y usa a Cappy para tomar el control de criaturas y objetos.'),
                                                                                                                           (5, 'Minecraft', 600, 'E10Plus', FALSE, 'Sandbox', 2, 'Explorá, reuní recursos y construí en un mundo abierto formado por bloques.'),
                                                                                                                           (6, 'Portal 2', 480, 'E10Plus', FALSE, 'Puzzles', 3, 'Resolvé cámaras de prueba con portales, objetos y mecanismos que cambian la forma de moverte.'),
                                                                                                                           (7, 'Stardew Valley', 3600, 'E10Plus', FALSE, 'Simulacion', 1, 'Convertí una granja heredada en tu hogar mientras cultivás, explorás y conocés al pueblo.'),
                                                                                                                           (8, 'God of War', 1200, 'M', FALSE, 'Accion', 3, 'Kratos y Atreus recorren reinos de la mitología nórdica en un viaje familiar.'),
                                                                                                                           (9, 'The Witcher 3: Wild Hunt', 3000, 'M', FALSE, 'RPG', 4, 'Geralt busca a Ciri y toma decisiones que afectan a los habitantes de un mundo abierto.'),
                                                                                                                           (10, 'Hollow Knight', 2400, 'E10Plus', FALSE, 'Aventura', 4, 'Explorá el reino subterráneo de Hallownest y desbloqueá habilidades para recorrer nuevas zonas.'),
                                                                                                                           (11, 'Dark Souls', 3000, 'M', TRUE, 'SoulsLike', 5, 'Recorré Lordran y enfrentá enemigos que exigen observar, aprender y medir cada ataque.'),
                                                                                                                           (12, 'Doom Eternal', 780, 'M', FALSE, 'Shooters', 4, 'Enfrentá hordas de demonios combinando movimiento rápido, armas y administración de recursos.'),
                                                                                                                           (13, 'Mario Kart 8 Deluxe', 600, 'E', FALSE, 'Carreras', 2, 'Competí en circuitos con personajes de Nintendo y usá objetos para cambiar la carrera.'),
                                                                                                                           (14, 'Civilization VI', 3000, 'E10Plus', FALSE, 'Estrategia', 4, 'Guiá una civilización a través de distintas épocas mediante exploración, diplomacia y estrategia.'),
                                                                                                                           (15, 'Resident Evil 4', 900, 'M', TRUE, 'Terror', 4, 'Leon investiga una desaparición en una aldea donde la munición y los recursos son limitados.');
INSERT INTO resenas (id_resena, id_contenido, id_usuario, tipo, calificacion, comentario, fecha) VALUES
                                                                                                     (1, 1, 1, 'PELICULA', 5, 'Una obra maestra, la volvería a ver mil veces.', '2026-10-02'),
                                                                                                     (2, 3, 4, 'PELICULA', 4, 'Muy buena, aunque el final me dejó dudas.', '2026-10-04'),
                                                                                                     (3, 5, 6, 'PELICULA', 3, 'Entretenida pero esperaba un poco más.', '2026-10-05'),
                                                                                                     (4, 10, 2, 'PELICULA', 5, 'Impecable de principio a fin.', '2026-10-07'),
                                                                                                     (5, 12, 14, 'PELICULA', 2, 'Se me hizo larga y algo confusa.', '2026-10-09'),
                                                                                                     (6, 1, 1, 'SERIE', 4, 'Excelente ambientación y muy buenas actuaciones.', '2026-10-11'),
                                                                                                     (7, 9, 4, 'SERIE', 1, 'No logró engancharme en ningún momento.', '2026-10-12'),
                                                                                                     (8, 7, 8, 'SERIE', 5, 'Me hizo reír y emocionarme a partes iguales.', '2026-10-15'),
                                                                                                     (9, 5, 10, 'SERIE', 3, 'Correcta, sin grandes sorpresas.', '2026-10-18'),
                                                                                                     (10, 15, 3, 'SERIE', 4, 'La banda sonora es increíble.', '2026-10-21'),
                                                                                                     (11, 1, 1, 'JUEGO', 5, 'Gran historia y personajes memorables.', '2026-10-24'),
                                                                                                     (12, 4, 5, 'JUEGO', 2, 'Tiene buenas ideas pero están mal aprovechadas.', '2026-10-27'),
                                                                                                     (13, 8, 12, 'JUEGO', 4, 'Ideal para ver en familia.', '2026-11-01'),
                                                                                                     (14, 13, 2, 'JUEGO', 3, 'Un clásico, aunque envejeció un poco.', '2026-11-05'),
                                                                                                     (15, 12, 6, 'JUEGO', 5, 'La recomiendo sin dudar.', '2026-11-10');
